UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 41, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 42, 7, NULL::text),(3, 170, 24, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 198, 1303, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='0a4ac2f0-6bcd-5f2a-8148-bbfb2fdfe907' AND md5(a.contenido)='b11fa22c0b1b0c4bda8dfa3173fcfc19' RETURNING a.id,md5(a.contenido) hash;